INSERT INTO orders (
    user_id
    , seller_id
    , product_price
    , shipping_fee
    , total_price
    , currency
    , exchange_rate
    , receiver_name
    , receiver_phone
    , shipping_country
    , shipping_zip
    , shipping_address
    , consumer_memo
) VALUES (
    #{userId}
    , #{sellerId}
    , #{productPrice}
    , IFNULL(#{shippingFee}, 0)
    , #{totalPrice}
    , IFNULL(#{currency}, 'USD')
    , #{exchangeRate}
    , #{receiverName}
    , #{receiverPhone}
    , #{shippingCountry}
    , #{shippingZip}
    , #{shippingAddress}
    , #{consumerMemo}
)

mapper.update:
UPDATE orders
SET status = #{status}
WHERE id = #{id}
